# Formatting-only overlay generated by Rust 1.99.1 rustfmt over the preserved donor.
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$source = Join-Path $root 'editor/lapce'
$patch = Join-Path $root 'editor/patches/codestrike-format.patch'
& git -C $source apply --check -- $patch
if ($LASTEXITCODE -ne 0) {
    # A prepared checkout may already contain this exact overlay. Never reset it.
    & git -C $source apply --reverse --check -- $patch
    if ($LASTEXITCODE -ne 0) { throw 'Formatting overlay does not match the prepared Lapce source.' }
    Write-Output 'Lapce formatting overlay already present.'
    exit 0
}
& git -C $source apply -- $patch
if ($LASTEXITCODE -ne 0) { throw 'Lapce formatting overlay failed.' }
